Definition imemcpy_words : list (bv 32) :=
  [W_85028; W_8502c; W_85030; W_85034; W_85038; W_8503c; W_85040; W_85044; W_85048].

(* [comment removed for export] *)
Definition imemcpy_clob : list reg := [11; 12; 13; 14].

